import{_ as e,o as i,c as s,aa as o}from"./chunks/framework.BAs_AphD.js";const h=JSON.parse('{"title":"Competency systém","description":"","frontmatter":{"title":"Competency systém","wiki":"en:tickets:permissions"},"headers":[],"relativePath":"en/tickets/permissions.md","filePath":"en/tickets/permissions.md","lastUpdated":1793088561000}'),n={name:"en/tickets/permissions.md"};function a(r,t,c,l,d,m){return i(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="competency-system" tabindex="-1">Competency systém <a class="header-anchor" href="#competency-system" aria-label="Permalink to &quot;Competency systém&quot;">​</a></h1><p>Every member of the construction project team can see only the tasks assigned to them.</p><p>The <strong>author</strong> of the task can edit it later without any limitations.</p><p>The task <strong>assignee</strong> can edit the following selected fields of the tasks:</p><ul><li>Status</li><li>Assignee</li><li>Actual Start and Actual End</li><li>Expression</li><li>Attachments</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For projects with a two or more tier structure of contractors, we recommend filling in the Assignee 1 field with a representative of the higher-level contractor and the Assignee 2 field with a representative of the subcontractor.</p></div><h2 id="project-administration" tabindex="-1">Project Administration <a class="header-anchor" href="#project-administration" aria-label="Permalink to &quot;Project Administration&quot;">​</a></h2><p>The administration of the project can be performed by the user who initiated the project or by a user who has been granted permissions at the Domain level.</p><p>The term Construction Administration includes the following activities:</p><ul><li>Editing construction information.</li><li>Editing the Project Team, which means assigning access to individual users for the specific construction project.</li><li>Editing Construction Parts and Drawings.</li><li>Editing Code lists- Construction project diary.</li><li>Editing Code lists- Task Management.</li></ul>',10)])])}const u=e(n,[["render",a]]);export{h as __pageData,u as default};
